package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class NamibiaGradeSevenNamesTest {
 private static final String NA="na-nied-primary-2024-v1";
 @Test public void gradeSevenPlacementKeepsThePublishedOneMillionLearningObjective(){var pack=GlobalCurriculum.packs("NA").stream().filter(p->p.id.equals(NA)).findFirst().orElseThrow();for(String id:List.of("englishWordsToNumber","numberToEnglishWords","largePlace",WholePlaceRelations.VALUE)){assertTrue(pack.inGrade(id,7));var limits=GlobalCurriculum.limits(NA,id,7);assertEquals(1000000,limits.wholeMaximum(-1));assertEquals(0,limits.givenMinimum(-1));Generator g=new Generator(new Random(300));List<String> recent=new ArrayList<>();for(int i=0;i<150;i++){Question q=g.next(id,recent,false,limits);assertFalse(recent.contains(q.signature()));recent.add(q.signature());int n=NumberPronunciation.supports(id)?EnglishNumberWords.publicValue(q):WholePlaceRelations.read(q).number();assertTrue(n>=0&&n<=1000000);assertFalse(HelpPlan.forQuestion(q).canTransfer());}}assertEquals(999999,GlobalCurriculum.limits(NA,"largePlace",6).wholeMaximum(-1));}
 @Test public void voiceUsesOnlyPublicEnglishGivensAndMarksWritingHelpSeparately(){for(int n:new int[]{0,21,1000,100005,1000000})for(String id:List.of("englishWordsToNumber","numberToEnglishWords")){Question q=EnglishNumberWords.make(id,n);q.answers=new String[]{"poison"};q.expression="poison";assertEquals(EnglishNumberWords.words(n),NumberPronunciation.text(q));assertEquals(id.equals("numberToEnglishWords"),NumberPronunciation.revealsWritingAnswer(q));assertTrue(new Checker().check(q,List.of(),List.of(id.equals("numberToEnglishWords")?EnglishNumberWords.words(n):""+n)).correct());}assertEquals("",NumberPronunciation.text(new Question("largePlace","12345에서 십의 자리 숫자는?","","4")));Question bad=EnglishNumberWords.make("englishWordsToNumber",3);bad.prompt="이 영어 수 이름을 숫자로 쓰세요.\nthree three";assertEquals("",NumberPronunciation.text(bad));}
 @Test public void everyDigitAndItsValueAreReconstructedFromPublicBoundaryNumbers(){for(int number:new int[]{0,5,999999,1000000})for(String name:List.of("일","십","백","천","만","십만","백만"))for(String id:List.of("largePlace",WholePlaceRelations.VALUE)){boolean value=id.equals(WholePlaceRelations.VALUE);Question q=new Question(id,number+"에서 "+name+"의 자리 숫자"+(value?"가 나타내는 값은?":"는?"),"poison","poison");var v=WholePlaceRelations.read(q);assertNotNull(v);int answer=v.digit()*(value?v.unit():1);assertTrue(new Checker().check(q,List.of(),List.of(""+answer)).correct());assertFalse(new Checker().check(q,List.of(),List.of(""+(answer+1))).correct());}Question malformed=new Question(WholePlaceRelations.VALUE,"100만에서 자리값?","","1000000");assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(malformed,List.of(),List.of("1000000")).status);}
}
